package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Mendengar Ayam atau Keldai", "Ya Allah, sesungguhnya aku memohon kepada-Mu tentang karunia-Mu (ayam jantan). - Aku berlindung kepada Allah dari syaitan, keledai yang terkutuk.", "Apabila mendengar ayam jantan meminta karunia Allah; apabila mendengar jeritan keldai, berlindung daripada syaitan.", "Ayam jantan melihat malaikat dan keldai melihat syaitan."),
        "dua_something_liked" to DuaText("Melihat Sesuatu yang Terpuji (Melawan Mata Jahat)", "Apa yang Allah kehendaki. Ya Allah, berkatilah.", "Apabila melihat sesuatu yang terpuji milik seseorang, berdoalah untuk diberkati.", "Berdoa untuk keberkatan mencegah mata jahat."),
        "dua_sell_buy_debt_repaid" to DuaText("Apabila Membayar Balik Hutang", "Semoga Allah merahmatimu dalam keluarga dan hartamu.", "Bagi pemberi pinjaman apabila membayar balik hutang.", "Pulangan untuk pinjaman adalah terima kasih dan pembayaran balik."),
        "dua_talbiyah" to DuaText("Talbiyah", "Inilah aku, Ya Allah, inilah aku. Inilah saya, Anda tiada pasangan, inilah saya. Sesungguhnya segala pujian, nikmat dan kekuasaan adalah milikMu. Anda tiada pasangan.", "Bersuara setelah masuk ihram.", "Lambang haji dan umrah."),
        "dua_yamani_hajar" to DuaText("Antara Rukn Yamani dan Hajar Aswad", "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari siksa neraka.", "Dalam tawaf, antara Sudut Yaman dan Hajar Aswad.", "Nabi ﷺ membaca ini di tempat ini dalam tawaf."),
        "dua_safa_marwa" to DuaText("Pada Safa dan Marwah", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian, dan Dia Maha Kuasa atas segala sesuatu. Tiada yang berhak disembah melainkan Allah sahaja; Dia memenuhi janji-Nya, menolong hamba-Nya dan sendirian mengalahkan konfederasi.", "Mendaki Safa dan menghadap kiblat (tiga kali).", "Zikir Nabi ﷺ tentang Safa dan Marwah."),
        "dua_arafah" to DuaText("Doa Terbaik Hari Arafah", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian, dan Dia Maha Kuasa atas segala sesuatu.", "Hari Arafah - doa yang terbaik.", "Doa yang terbaik adalah do'a hari Arafah, dan sebaik-baik perkataan adalah ini."),
        "dua_takbeer_tashreeq" to DuaText("Takbir-e-Tasyriq", "Allah Maha Besar, Allah Maha Besar. Tiada tuhan selain Allah. Allah Maha Besar, Allah Maha Besar, dan segala puji bagi Allah.", "Selepas setiap solat fardhu dari Subuh 9 Zulhijjah hingga Asar 13 Zulhijjah.", "Diriwayatkan dari Ali dan Ibnu Mas'ud (RA) — wajib menurut Hanafi."),
        "dua_zamzam" to DuaText("Minum Zamzam", "Ya Allah, sesungguhnya aku memohon kepadaMu ilmu yang bermanfaat, rezeki yang melimpah dan kesembuhan dari setiap penyakit.", "Apabila minum zamzam, berdoalah untuk apa yang kamu niatkan.", "Zamzam adalah untuk apa sahaja yang diminumnya (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Merenung Penciptaan", "Ya Tuhan kami, Engkau tidak menciptakan semua ini dengan sia-sia. Maha Suci Engkau, maka peliharalah kami dari siksa neraka.", "Doa orang yang memikirkan tentang penciptaan langit dan bumi.", "Doa orang yang berakal (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Kami Mendengar Penyeru kepada Iman", "Ya Tuhan kami, kami mendengar seorang yang menyeru kepada iman, berkata: \"Berimanlah kamu kepada Tuhanmu\", lalu kami pun beriman. Ya Tuhan kami, ampunilah dosa-dosa kami, hapuskanlah kesalahan-kesalahan kami dan wafatkanlah kami beserta orang-orang yang berbakti.", "Doa untuk iman dan mati dalam kalangan orang-orang yang soleh.", "Doa untuk pengampunan dan pengakhiran yang baik."),
        "dua_q_atina_ma_waadtana" to DuaText("Berikan Kami Apa Yang Anda Janjikan", "Ya Tuhan kami, berikanlah kepada kami apa yang telah Engkau janjikan kepada kami melalui rasul-rasulMu dan janganlah Engkau hinakan kami pada hari kiamat. Sesungguhnya Engkau tidak memungkiri janji.", "Berlindung dari kehinaan pada hari kiamat.", "Mencari kemuliaan di akhirat."),
        "dua_q_israfana" to DuaText("Maafkan Keterlaluan Kami", "Ya Tuhan kami, ampunilah dosa-dosa kami dan tindakan-tindakan kami yang berlebih-lebihan dalam urusan kami, tetapkanlah pendirian kami dan tolonglah kami terhadap kaum yang kafir.", "Doa para sahabat Nabi terdahulu.", "Doa untuk keteguhan dan pengampunan."),
        "dua_q_jamiun_nas" to DuaText("Anda Akan Mengumpul Umat Manusia", "Ya Tuhan kami, sesungguhnya Engkau akan mengumpulkan manusia pada hari yang tidak ada keraguan padanya. Sesungguhnya Allah tidak memungkiri janji.", "Meneguhkan kepastian di hari kiamat.", "Doa orang-orang yang teguh dalam ilmu."),
        "dua_q_maash_shahidin" to DuaText("Tulis Kami Antara Saksi", "Ya Tuhan kami, kami telah beriman, maka tulislah kami di antara orang-orang yang menjadi saksi.", "Doa orang-orang yang mengakui kebenaran dan beriman.", "Doa untuk diterima iman seseorang."),
        "dua_q_la_tajalna_zalimin" to DuaText("Bukan Bersama Orang Yang Zalim", "Ya Tuhan kami, janganlah Engkau jadikan kami bersama orang-orang yang zalim.", "Doa penduduk al-A'raf.", "Berlindung dari nasib orang-orang yang zalim."),
        "dua_q_tawaffana_muslimin" to DuaText("Sabar dan Mati sebagai umat Islam", "Ya Tuhan kami, limpahkanlah kesabaran kepada kami dan wafatkanlah kami dalam keadaan muslim.", "Doa ahli sihir Firaun ketika mereka beriman.", "Sabar dalam ujian dan pengakhiran atas iman."),
        "dua_q_la_tajalna_fitnah" to DuaText("Bukan Percubaan untuk Penindas", "Kepada Allah kita berserah. Ya Tuhan kami, janganlah Engkau jadikan kami cobaan bagi orang-orang yang zalim, dan selamatkanlah kami dengan rahmat-Mu dari orang-orang yang kafir.", "Doa kaum Musa (AS).", "Doa untuk menyelamatkan dari penindasan dan penindas."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Doa Nuh (AS) untuk Pengampunan", "Ya Tuhanku, aku berlindung kepada-Mu dari memohon kepada-Mu sesuatu yang aku tidak mengetahuinya. Dan jika Engkau tidak mengampuni aku dan memberi rahmat kepadaku, nescaya aku termasuk orang-orang yang rugi.", "Doa taubat Nabi Nuh (AS).", "Pengajaran dalam bertanya dengan adab yang betul."),
        "dua_q_mudkhala_sidq" to DuaText("Masuk dan Keluar Kebenaran", "Ya Tuhanku, masukkanlah aku dengan kebenaran dan keluarkanlah aku dengan kebenaran, dan berikanlah kepadaku dari sisi-Mu kekuasaan yang menolong.", "Sebelum memasuki tugas, rumah atau tempat baharu.", "Doa yang diajarkan kepada Nabi ﷺ pada masa Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Doa Zakariya (AS) — Jangan Tinggalkan Aku Sendirian", "Ya Tuhanku, janganlah Engkau biarkan aku seorang diri, dan Engkaulah pewaris yang terbaik.", "Bagi yang mencari anak.", "Melalui doa ini Allah menganugerahkan Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Tempat Pendaratan yang Diberkati", "Ya Tuhanku, izinkan aku mendarat di tempat yang diberkati, dan Engkau adalah sebaik-baik yang membawa ke darat.", "Apabila berpindah ke rumah baru atau berhenti di suatu tempat — doa Nuh (AS).", "Doa untuk keberkatan di tempat baru."),
        "dua_q_amanna_faghfir" to DuaText("Kami Percaya, Maka Maafkan Kami", "Ya Tuhan kami, kami telah beriman, maka ampunilah kami dan rahmatilah kami, dan Engkau adalah Pemberi rahmat yang paling baik.", "Doa hamba-hamba Allah yang soleh.", "Doa yang menyeluruh untuk ampunan dan rahmat."),
        "dua_q_isrif_jahannam" to DuaText("Jauhilah azab Neraka", "Ya Tuhan kami, jauhkanlah azab neraka Jahannam dari kami; sesungguhnya azabnya adalah tetap. Sesungguhnya ia adalah penempatan dan tempat tinggal yang jahat.", "Doa hamba-hamba Tuhan Yang Maha Pemurah ('Ibad ar-Rahman).", "Doa Al-Quran untuk berlindung dari Neraka."),
        "dua_q_hab_li_hukman" to DuaText("Doa Ibrahim (AS) — Hikmah dan Jannah", "Ya Tuhanku, kurniakanlah kepadaku hikmah dan masukkanlah aku ke dalam golongan orang-orang yang soleh, anugerahkanlah kepadaku sebutan yang mulia di antara umat-umat yang kemudian, dan jadikanlah aku termasuk orang-orang yang mewarisi Syurga yang penuh kenikmatan.", "Meminta kebijaksanaan, kumpulan orang-orang soleh dan syurga.", "Doa Ibrahim (AS) yang menyeluruh."),
        "dua_q_lut_najjini_ahli" to DuaText("Doa Lut (AS) — Selamatkan Keluargaku", "Ya Tuhanku, selamatkanlah aku dan keluargaku dari (akibat) apa yang mereka kerjakan.", "Melindungi keluarga daripada persekitaran yang jahat.", "Perlindungan keluarga daripada kejahatan."),
        "dua_q_sulaiman_awzini" to DuaText("Doa Sulaiman (AS) untuk Syukur", "Ya Tuhanku, berilah aku ilham untuk tetap mensyukuri nikmat-Mu yang telah Engkau anugerahkan kepadaku dan kepada dua orang ibu bapakku, dan untuk mengerjakan amal saleh yang Engkau ridhai, dan masukkanlah aku dengan rahmat-Mu ke dalam golongan hamba-hamba-Mu yang saleh.", "Untuk kemampuan untuk mensyukuri nikmat.", "Doa kesyukuran Sulaiman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Doa Musa (AS) — Aku Bersalah Diriku", "Ya Tuhanku, aku telah menganiaya diriku sendiri, maka ampunilah aku.", "Segera bertaubat setelah melakukan kesalahan.", "Allah mengampuni Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Doa Musa (AS) — Selamatkan Aku daripada Penindas", "Ya Tuhanku, selamatkanlah aku dari kaum yang zalim.", "Apabila takut kepada penindas.", "Doa Musa (AS) ketika meninggalkan Mesir."),
        "dua_q_lut_unsurni" to DuaText("Doa Lut (AS) — Bantuan Melawan Rasuah", "Ya Tuhanku, tolonglah aku terhadap orang-orang yang berbuat kerusakan.", "Untuk bantuan terhadap mereka yang menyebarkan rasuah.", "Doa orang-orang yang berdiri teguh di atas kebenaran."),
        "dua_q_hab_li_salihin" to DuaText("Doa Ibrahim (AS) untuk Anak yang Soleh", "Ya Tuhanku, anugerahkanlah kepadaku (seorang anak) yang termasuk orang-orang yang saleh.", "Meminta anak yang soleh.", "Melalui doa ini dimakbulkan Isma'il (AS)."),
        "dua_q_wasita_kulla_shay" to DuaText("Doa Malaikat Menanggung Arasy", "Ya Tuhan kami, rahmat dan ilmu Engkau meliputi segala sesuatu, maka ampunilah orang-orang yang bertaubat dan mengikuti jalan-Mu, dan peliharalah mereka dari siksa neraka.", "Para malaikat yang memikul Arasy berdoa ini untuk orang-orang yang beriman.", "Dibaca dengan niat untuk dimasukkan dalam doa malaikat."),
        "dua_q_ikhwanina" to DuaText("Untuk Saudara Kita Yang Mendahului Kita", "Ya Tuhan kami, ampunilah kami dan saudara-saudara kami yang telah beriman mendahului kami, dan janganlah Engkau membiarkan kedengkian dalam hati kami terhadap orang-orang yang beriman. Ya Tuhan kami, sesungguhnya Engkau Maha Pengasih lagi Maha Penyayang.", "Doa untuk orang mukmin yang terdahulu dan untuk hati yang bersih.", "Doa untuk para Sahabat yang mulia (RA) dan orang-orang mukmin yang terdahulu."),
        "dua_q_alayka_tawakkalna" to DuaText("KepadaMu Kami Bertawakal (Ibrahim AS)", "Ya Tuhan kami, kepada Engkaulah kami bertawakkal, kepada Engkaulah kami kembali dan kepada Engkaulah tempat kembali. Ya Tuhan kami, janganlah Engkau jadikan kami ujian bagi orang-orang kafir dan ampunilah kami. Ya Tuhan kami, sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.", "Doa Ibrahim (AS) dan para sahabatnya.", "Doa tawakkal kepada Allah dan kembali kepada-Nya."),
        "dua_q_atmim_nurana" to DuaText("Sempurnakan Cahaya Kita", "Ya Tuhan kami, sempurnakanlah bagi kami cahaya kami dan ampunilah kami. Sesungguhnya Engkau Maha Kuasa atas segala sesuatu.", "Doa orang mukmin pada hari kiamat.", "Meminta cahaya pada Sirat."),
        "dua_q_asiya_baytan" to DuaText("Doa Asiya — Rumah di Jannah", "Ya Tuhanku, bangunkanlah untukku sebuah rumah di sisi-Mu dalam surga, selamatkanlah aku dari Firaun dan perbuatannya, dan selamatkanlah aku dari kaum yang zalim.", "Doa Asiya, isteri Firaun.", "Allah menjadikan dia contoh bagi orang-orang yang beriman."),
        "dua_adhan_response" to DuaText("Menjawab adzan", "Tiada daya dan kekuatan melainkan dengan pertolongan Allah.", "Ulangi apa yang dikatakan muazin; at 'Hayya 'alas-salah' dan 'Hayya 'alal-falah' katakan ini.", "Barangsiapa yang menjawab dari hati akan masuk surga."),
        "dua_adhan_shahadah" to DuaText("Selepas Shahadah Muazzin", "Dan aku juga bersaksi bahawa tiada yang berhak disembah melainkan Allah semata-mata, tiada sekutu bagi-Nya, dan bahawa Muhammad ﷺ adalah hamba dan Rasul-Nya. Saya redha Allah sebagai Tuhan, Muhammad ﷺ sebagai Rasul dan Islam sebagai agama.", "Apabila mendengar keterangan muazin tentang iman.", "Dosanya diampuni."),
        "dua_istiftah_baid" to DuaText("Doa Pembukaan: Jauhkan Aku dari Dosa", "Ya Allah jauhkanlah aku dari dosa-dosaku sebagaimana Engkau menjauhkan timur dari barat. Ya Allah, bersihkanlah aku dari dosa sebagaimana pakaian putih dibersihkan dari kotoran. Ya Allah, bersihkanlah dosa-dosaku dengan air, salji dan hujan es.", "Selepas takbir pembukaan (boleh juga disebut sebagai ganti Sana).", "Nabi ﷺ membaca ini antara takbir dan bacaan."),
        "dua_hamdan_kathiran" to DuaText("Pujian yang Banyak Selepas Ruku", "Ya Tuhan kami, bagi-Mulah pujian - pujian yang melimpah, suci dan penuh berkah.", "Setelah bangkit dari ruku, bersama dengan 'Rabbana lakal-hamd'.", "Lebih daripada tiga puluh malaikat berlumba-lumba untuk menjadi yang pertama merakamnya."),
    )
}
